import selfies as sf
from rdkit import Chem
from rdkit.Chem import Descriptors
xs=['[C][C][Branch1][C][C][Branch1][C][C][O][C][=Branch1][C][=O][O][C][=Branch1][C][=O][O][C][Branch1][C][C][Branch1][C][C][C]','[C][N]','[C][C][C][O][C][Ring1][Branch1]']
for i,x in enumerate(xs,1):
    try:
        sm=sf.decoder(x)
        m=Chem.MolFromSmiles(sm)
        print(i,'decoded:',sm)
        print('canonical:',Chem.MolToSmiles(m) if m else None)
        if m: print('formula atoms MW:',Descriptors.MolWt(m),m.GetNumAtoms())
    except Exception as e: print(i,'ERROR',repr(e))
